def clean(df):
    df = df.copy()
    # normalize sex: case variants MALE/FEMALE -> male/female
    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype('string').str.strip().str.lower()
        # keep only allowed values, others become NA (missing means unknown)
        allowed_sex = {'male', 'female'}
        df.loc[~df['sex'].isin(allowed_sex), 'sex'] = pd.NA
    # normalize island: typo variants Torgerson->Torgersen, Bisco->Biscoe
    if 'island' in df.columns:
        df['island'] = df['island'].astype('string').str.strip()
        island_map = {'Torgerson': 'Torgersen', 'Bisco': 'Biscoe'}
        df['island'] = df['island'].replace(island_map)
    # body_mass_g is text with commas like "5,500" and out-of-range 4000000
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = df['body_mass_g'].astype('string').str.replace(',', '', regex=False).str.strip()
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
        # out_of_range per rules min 2500 max 6500
        df.loc[(df['body_mass_g'] < 2500) | (df['body_mass_g'] > 6500), 'body_mass_g'] = pd.NA
    # ensure other numeric columns are numeric and within range (defensive)
    if 'bill_length_mm' in df.columns:
        df['bill_length_mm'] = pd.to_numeric(df['bill_length_mm'], errors='coerce')
        df.loc[(df['bill_length_mm'] < 30) | (df['bill_length_mm'] > 60), 'bill_length_mm'] = pd.NA
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
        df.loc[(df['flipper_length_mm'] < 170) | (df['flipper_length_mm'] > 235), 'flipper_length_mm'] = pd.NA
    return df

def answer(df):
    # ensure cleaned
    df = clean(df)
    # drop missing group keys and missing measure
    df = df.dropna(subset=['species', 'body_mass_g'])
    if df.empty:
        return {}
    grouped = df.groupby('species', dropna=True)['body_mass_g'].mean()
    # return dict with string keys and float values
    return {str(k): float(v) for k, v in grouped.items()}
